import { useSelector } from "react-redux";
import { useDispatch } from "react-redux";
import { fetchMoviesAsync } from "../Features/MoviesSlice";
import { useEffect, useState } from "react";
import { Table, Container } from 'react-bootstrap';
import ReactPaginate from 'react-paginate';
import 'bootstrap/dist/css/bootstrap.min.css';
import { Link } from 'react-router-dom';
import '../styles/index.css'

export default function Index() {
    const dispatch = useDispatch();
    const { movies, status, error } = useSelector((state) => state.movies);
    const [currentPage, setCurrentPage] = useState(0);
    const itemsPerPage = 5;

    useEffect(() => {
        dispatch(fetchMoviesAsync());
    }, [dispatch]);

    if (status === 'loading') {
        return <p>Cargando películas...</p>;
    }

    if (status === 'failed') {
        return <p>Error: Ocurrió un error al cargar las películas</p>;
    }

    const handlePageClick = (data) => {
        setCurrentPage(data.selected);
    };

    if (status === 'succeeded') {
        const filteredMovies = movies && Array.isArray(movies.entries) 
            ? movies.entries.filter(movie => movie.programType === "movie") 
            : [];

        const offset = currentPage * itemsPerPage;
        const currentItems = filteredMovies.slice(offset, offset + itemsPerPage);

        return (
            <div className="index-container">
                <div className="button-container">
                    <div className="button-wrapper">
                        <Link to="/series" className="button-link">
                            <div className="button-content">
                                <div className="button-title">Series</div>
                            </div>
                        </Link>
                        <div className="button-subtitle">Popular Series</div>
                    </div>
                    <div className="button-wrapper">
                        <Link to="/peliculas" className="button-link">
                            <div className="button-content">
                                <div className="button-title">Movies</div>
                            </div>
                        </Link>
                        <div className="button-subtitle">Popular Movies</div>
                    </div>
                </div>
            </div>
        );
    }

    
}
